sp_widget.client_script:
api.controller = function($scope, spUtil) {
  var c = this;

  c.hasRecord = function() {
    return !!c.data.record && !!c.data.record.sys_id;
  };

  c.isProcessing = false;
  c.isSaving = false;

  c.processPrompt = function() {
    if (!c.hasRecord() || c.isProcessing) {
      return;
    }
    c.isProcessing = true;
    c.errorMessage = '';

    spUtil.get('prompt_record', {
      action: 'process',
      sys_id: c.data.record.sys_id
    }).then(function(response) {
      if (response && response.data) {
        if (response.data.error) {
          c.errorMessage = response.data.error;
        }
        if (response.data.record) {
          c.data.record = response.data.record;
        }
      }
    }).finally(function() {
      c.isProcessing = false;
    });
  };

  c.save = function() {
    if (!c.hasRecord() || c.isSaving) {
      return;
    }
    c.isSaving = true;
    c.errorMessage = '';

    spUtil.get('prompt_record', {
      action: 'save',
      sys_id: c.data.record.sys_id,
      prompt: c.data.record.prompt,
      result: c.data.record.result
    }).then(function(response) {
      if (response && response.data) {
        if (response.data.error) {
          c.errorMessage = response.data.error;
        }
        if (response.data.record) {
          c.data.record = response.data.record;
        }
      }
    }).finally(function() {
      c.isSaving = false;
    });
  };
};

sp_widget.script:
(function() {
  // Read sys_id from URL: /sp?id=prompt_record&sys_id=...
  data.record = {};

  // Handle action from client (process integration)
  if (input && input.action === 'process' && input.sys_id) {
    var current = new GlideRecord('x_107457_test_prompt');
    if (current.get(input.sys_id)) {
      current.update();
      new x_107457_test.PromptUtils().execute(current);

      data.record = {
        sys_id: current.getUniqueValue(),
        number: current.getDisplayValue('number') || '',
        user: current.getDisplayValue('user'),
        article: current.getDisplayValue('article'),
        prompt: current.getDisplayValue('prompt'),
        result: current.getDisplayValue('result'),
        summary: current.getDisplayValue('summary'),
        created_on: current.getDisplayValue('sys_created_on'),
        updated_on: current.getDisplayValue('sys_updated_on')
      };
    } else {
      data.error = 'Prompt record not found.';
    }
    return;
  }

  // Handle save from client
  if (input && input.action === 'save' && input.sys_id) {
    var saveGr = new GlideRecord('x_107457_test_prompt');
    if (saveGr.get(input.sys_id)) {
      if (typeof input.prompt === 'string') {
        saveGr.setValue('prompt', input.prompt);
      }
      if (typeof input.result === 'string') {
        saveGr.setValue('result', input.result);
      }
      saveGr.update();

      data.record = {
        sys_id: saveGr.getUniqueValue(),
        number: saveGr.getDisplayValue('number') || '',
        user: saveGr.getDisplayValue('user'),
        article: saveGr.getDisplayValue('article'),
        prompt: saveGr.getDisplayValue('prompt'),
        result: saveGr.getDisplayValue('result'),
        summary: saveGr.getDisplayValue('summary'),
        created_on: saveGr.getDisplayValue('sys_created_on'),
        updated_on: saveGr.getDisplayValue('sys_updated_on')
      };
    } else {
      data.error = 'Prompt record not found.';
    }
    return;
  }

  var sysId = $sp.getParameter('sys_id');

  if (!sysId) {
    data.error = 'No record specified.';
    return;
  }

  var gr = new GlideRecord('x_107457_test_prompt');
  if (!gr.get(sysId)) {
    data.error = 'Prompt record not found.';
    return;
  }

  data.record = {
    sys_id: gr.getUniqueValue(),
    number: gr.getDisplayValue('number') || '',
    user: gr.getDisplayValue('user'),
    article: gr.getDisplayValue('article'),
    prompt: gr.getDisplayValue('prompt'),
    result: gr.getDisplayValue('result'),
    summary: gr.getDisplayValue('summary'),
    created_on: gr.getDisplayValue('sys_created_on'),
    updated_on: gr.getDisplayValue('sys_updated_on')
  };
})();
